package com.bank.spark.service;

import com.bank.spark.model.Transaction;

import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

// Simulates a broadcast hash join: the small table is a map held on every executor.
public class BroadcastHashJoiner {

    private final Map<String, String> broadcastBranchNames; // branchId -> branchName

    public BroadcastHashJoiner(Map<String, String> broadcastBranchNames) {
        this.broadcastBranchNames = broadcastBranchNames;  // "broadcast" copy
    }

    // Join one executor's LOCAL partition of transactions — NO shuffle.
    public List<String> joinLocalPartition(int executorId, List<Transaction> localTxns) {
        return localTxns.stream()
                .map(t -> "exec" + executorId + ": " + t.getTxnId()
                        + " branch=" + broadcastBranchNames.getOrDefault(t.getBranchId(), "UNKNOWN")
                        + " amount=" + t.getAmount())
                .collect(Collectors.toList());
    }
}
