package com.bank.spark;

import com.bank.spark.model.Transaction;
import com.bank.spark.service.BroadcastHashJoiner;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class BroadcastJoinDemo {

    private static final Logger log = Logger.getLogger(BroadcastJoinDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // The SMALL branch dimension — broadcast to every executor.
        Map<String, String> branches = Map.of(
                "BR-MUM", "Mumbai Main",
                "BR-DEL", "Delhi Central",
                "BR-CHE", "Chennai South"
        );
        log.info(() -> "Broadcasting branch dimension (" + branches.size() + " rows) to all executors");

        BroadcastHashJoiner joiner = new BroadcastHashJoiner(branches);

        // Two executors, each with its own LOCAL partition of the huge transactions table.
        List<Transaction> exec1 = List.of(
                new Transaction("T1", "BR-MUM", new BigDecimal("50000")),
                new Transaction("T2", "BR-DEL", new BigDecimal("12000"))
        );
        List<Transaction> exec2 = List.of(
                new Transaction("T3", "BR-CHE", new BigDecimal("90000")),
                new Transaction("T4", "BR-MUM", new BigDecimal("30000"))
        );

        joiner.joinLocalPartition(1, exec1).forEach(log::info);
        joiner.joinLocalPartition(2, exec2).forEach(log::info);

        log.info("Large transactions table was NEVER shuffled — each executor joined its local partition.");
    }
}

